function render({width,state,params}) {
  const W = Number.isFinite(width) ? Math.max(320,Math.min(760,width)) : 320;
  const H = 260;
  const supplied = params && params.eta;
  const eta = Number.isFinite(supplied) ? Math.max(0.05,Math.min(1.2,supplied)) : 0.2;
  const focus = state === 'curvature' ? 'curvature' : 'change';
  const ink = '#292722', blue = '#286c9c', orange = '#cb702c', quiet = '#c9c5bb';
  const x0 = 10, gradient = 20, deltaX = -eta*gradient;
  const x1 = x0+deltaX, f0 = x0*x0, f1 = x1*x1;
  const linear = gradient*deltaX, quadratic = deltaX*deltaX, change = f1-f0;
  const q = 1-2*eta, magnitude = Math.abs(q);
  const regime = magnitude < 1-1e-12 ? '收缩' : magnitude > 1+1e-12 ? '放大' : '保持';
  const fmt = n => (Math.abs(n)<0.0000001 ? 0 : n).toFixed(2);
  const left = 24, right = W-24, domain = [-500,600];
  const X = v => left+(v-domain[0])/(domain[1]-domain[0])*(right-left);
  const zero = X(0);
  const definitions = [
    {key:'linear',label:'一阶项',value:linear,color:blue,y:78},
    {key:'quadratic',label:'二阶项',value:quadratic,color:orange,y:124},
    {key:'change',label:'实际 Δf',value:change,color:ink,y:170}
  ];
  let body = '<rect width="'+W+'" height="'+H+'" fill="#faf8f2"/>';
  const text = (x,y,t,anchor='start',color=ink) => '<text x="'+x+'" y="'+y+'" text-anchor="'+anchor+'" fill="'+color+'" font-size="14">'+t+'</text>';
  body += text(16,21,'η='+fmt(eta)+'   x₁='+fmt(x1)+'   f₁='+fmt(f1));
  body += text(16,43,'f(x)=x² · x₀=10');
  body += '<line x1="'+zero+'" y1="61" x2="'+zero+'" y2="203" stroke="'+quiet+'"/>';
  const rows = definitions.map(row => {
    const endpoint = X(row.value), rectX = Math.min(zero,endpoint), rectWidth = Math.abs(endpoint-zero);
    const active = focus === 'curvature' ? row.key === 'quadratic' : row.key === 'change';
    body += text(left,row.y-8,row.label);
    body += text(right,row.y-8,fmt(row.value),'end');
    body += '<rect x="'+rectX+'" y="'+row.y+'" width="'+rectWidth+'" height="12" fill="'+row.color+'" opacity="'+(active ? 1 : 0.55)+'"/>';
    return {key:row.key,value:row.value,color:row.color,rectangle:{x:rectX,y:row.y,width:rectWidth,height:12},emphasized:active};
  });
  body += '<line x1="'+left+'" y1="203" x2="'+right+'" y2="203" stroke="'+quiet+'"/>';
  [-400,0,400].forEach(v => {
    const px = X(v);
    body += '<line x1="'+px+'" y1="203" x2="'+px+'" y2="208" stroke="'+quiet+'"/>';
    body += text(px,225,String(v),'middle');
  });
  body += text(16,249,'|1−2η|='+fmt(magnitude)+' · '+regime);
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" role="img"><title>一步更新的收支</title><desc>横条长度表示函数值变化，三行使用相同尺度。蓝色是一阶项，橙色是二阶项，墨色是实际变化。当前学习率为'+fmt(eta)+'，实际变化为'+fmt(change)+'。</desc><g font-family="sans-serif">'+body+'</g></svg>';
  return {svg,facts:{width:W,height:H,state:focus,objective:'x^2',eta,initial:{x:x0,f:f0,gradient},update:{deltaX,x:x1,f:f1},decomposition:{linear,quadratic,actual:change,sum:linear+quadratic},iterationMultiplier:q,magnitudeMultiplier:magnitude,regime,barAxis:{domain,pixelRange:[left,right],zeroPixel:zero,quantity:'函数值变化'},rows}};
}

function render({width,state,params}) {
  const W = Number.isFinite(width) ? Math.max(320,Math.min(760,width)) : 320;
  const narrow = W < 540, H = narrow ? 330 : 250;
  const supplied = params && params.kappa;
  const kappa = Number.isFinite(supplied) ? Math.max(1,Math.min(12,supplied)) : 2;
  const eta = 0.1, start = [-5,-2], gradient = [-10,-4*kappa], diagonal = [2,2*kappa];
  const ink = '#292722', blue = '#286c9c', orange = '#cb702c', quiet = '#c9c5bb';
  const fmt = n => (Math.abs(n)<0.0000001 ? 0 : n).toFixed(2);
  const value = p => p[0]*p[0]+kappa*p[1]*p[1];
  const text = (x,y,t,anchor='start',color=ink) => '<text x="'+x+'" y="'+y+'" text-anchor="'+anchor+'" font-size="14" fill="'+color+'">'+t+'</text>';
  const methods = [
    {key:'ordinary',label:'普通：Δx=−ηg',delta:gradient.map(g => -eta*g),multipliers:[1-2*eta,1-2*kappa*eta]},
    {key:'diagonal',label:'对角预处理：Δx=−ηD⁻¹g',delta:gradient.map((g,i) => -eta*g/diagonal[i]),multipliers:[1-eta,1-eta]}
  ];
  let body = '<rect width="'+W+'" height="'+H+'" fill="#faf8f2"/>';
  body += text(16,21,'f=x₁²+κx₂²   κ='+kappa.toFixed(1)+'   η=0.1');
  const panels = methods.map((method,index) => {
    const base = narrow ? 0 : index*W/2;
    const top = narrow ? 34+index*146 : 39;
    const panelWidth = narrow ? W : W/2;
    const availableWidth = Math.min(narrow ? 145 : 180,panelWidth-(narrow ? 160 : 144));
    const availableHeight = narrow ? 98 : 130;
    const scale = Math.min(availableWidth/7,availableHeight/6.5);
    const px = base+36, py = top+28, pw = 7*scale, ph = 6.5*scale;
    const X = x => px+(x+6)*scale;
    const Y = y => py+(3.5-y)*scale;
    const end = start.map((v,i) => v+method.delta[i]);
    const startPixel = [X(start[0]),Y(start[1])], endPixel = [X(end[0]),Y(end[1])];
    const clipId = 'diagonal-coordinate-step-'+method.key;
    body += text(base+14,top+15,method.label);
    body += '<defs><clipPath id="'+clipId+'"><rect x="'+px+'" y="'+py+'" width="'+pw+'" height="'+ph+'"/></clipPath></defs>';
    const contours = [4,16,36].map(level => ({level,cx:X(0),cy:Y(0),rx:Math.sqrt(level)*scale,ry:Math.sqrt(level/kappa)*scale}));
    body += '<g clip-path="url(#'+clipId+')">';
    contours.forEach(c => { body += '<ellipse cx="'+c.cx+'" cy="'+c.cy+'" rx="'+c.rx+'" ry="'+c.ry+'" fill="none" stroke="'+blue+'" stroke-width="1.2" opacity="0.6"/>'; });
    body += '<line x1="'+px+'" y1="'+Y(0)+'" x2="'+(px+pw)+'" y2="'+Y(0)+'" stroke="'+quiet+'"/>';
    body += '<line x1="'+X(0)+'" y1="'+py+'" x2="'+X(0)+'" y2="'+(py+ph)+'" stroke="'+quiet+'"/>';
    body += '<line x1="'+startPixel[0]+'" y1="'+startPixel[1]+'" x2="'+endPixel[0]+'" y2="'+endPixel[1]+'" stroke="'+orange+'" stroke-width="2.2"/>';
    const dx = endPixel[0]-startPixel[0], dy = endPixel[1]-startPixel[1], length = Math.hypot(dx,dy);
    const ux = length > 0 ? dx/length : 1, uy = length > 0 ? dy/length : 0;
    const headLength = Math.min(7,length*0.4), halfWidth = headLength*0.45;
    const arrowHead = [endPixel,[endPixel[0]-headLength*ux-halfWidth*uy,endPixel[1]-headLength*uy+halfWidth*ux],[endPixel[0]-headLength*ux+halfWidth*uy,endPixel[1]-headLength*uy-halfWidth*ux]];
    body += '<polygon points="'+arrowHead.map(p => p.join(',')).join(' ')+'" fill="'+orange+'"/>';
    body += '<circle cx="'+startPixel[0]+'" cy="'+startPixel[1]+'" r="3.2" fill="#faf8f2" stroke="'+ink+'" stroke-width="1.5"/>';
    body += '<circle cx="'+endPixel[0]+'" cy="'+endPixel[1]+'" r="2.8" fill="'+orange+'"/>';
    body += '</g>';
    [-5,0].forEach(v => { body += text(X(v),py+ph+17,String(v),'middle'); });
    [-2,0].forEach(v => { body += text(px-7,Y(v)+5,String(v),'end'); });
    body += text(px+pw,py+ph+17,'x₁','start');
    body += text(px-27,py+14,'x₂');
    const infoX = px+pw+12;
    body += text(infoX,top+47,'Δx₁='+fmt(method.delta[0]));
    body += text(infoX,top+69,'Δx₂='+fmt(method.delta[1]));
    body += text(infoX,top+91,'f₁='+fmt(value(end)));
    body += text(infoX,top+113,'x₁ × '+fmt(method.multipliers[0]));
    body += text(infoX,top+135,'x₂ × '+fmt(method.multipliers[1]));
    return {method:method.key,initial:start.slice(),gradient:gradient.slice(),delta:method.delta,end,f0:value(start),f1:value(end),coordinateMultipliers:method.multipliers,parameterDomain:{x1:[-6,1],x2:[-3,3.5]},pixelsPerUnit:{x1:scale,x2:scale},clipRectangle:{x:px,y:py,width:pw,height:ph},contours,startPixel,endPixel,arrowHead};
  });
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" role="img"><title>各坐标的一步</title><desc>空心点是初始参数，橙色箭头是一次参数更新，蓝色椭圆是目标函数等值线。两个平面的横纵单位尺度相同。当前曲率系数为'+kappa.toFixed(1)+'，比较普通梯度下降与正定对角Hessian预处理。</desc><g font-family="sans-serif">'+body+'</g></svg>';
  return {svg,facts:{width:W,height:H,state:'compare',layout:narrow ? 'vertical' : 'horizontal',objective:'x1^2+kappa*x2^2',kappa,eta,hessian:[[2,0],[0,2*kappa]],diagonal,contourLevels:[4,16,36],panels}};
}
